import { useContext, useEffect, useLayoutEffect, useRef, useState } from 'react';
import type { ComponentType, ReactNode, RefObject } from 'react';
import css from './Reader.module.css';
import { settleByDeadline } from './animation-deadline.js';
import { SPINNER_INTERVAL_MS, SPINNER_STILL_FRAME, spinnerFrame } from './spinner.js';
import { StreamMotionContext } from './streaming.js';
import { jumpLock } from './jump-lock.js';
import { ui } from './locale.js';

const EASING = 'cubic-bezier(.22,1,.36,1)';

/** This view's definition of "a record a reader can read" — the same marker the
 *  reading-anchor capture uses, so the unread badge and the anchor agree about
 *  what counts as content. */
const RECORD = '[data-reader-anchor]';

/** Two digits is all the badge is worth: "12" tells a reader to go back, and
 *  "1284" tells them nothing the rest of the control does not already. */
const UNREAD_CAP = 99;

/**
 * Count the records in one batch of DOM mutations.
 *
 * Split out of the observer because it is the whole of the unread rule, and the
 * rule is worth testing without a browser: a count that double-counts nested
 * records, or that counts a text node as a record, is worse than no count — it
 * tells the reader to go back for something that is not there.
 *
 * `closest` is deliberately not consulted: an added subtree counts as one
 * record for each record inside it, however deep, which is what a batch of
 * newly-arrived turns looks like to React.
 */
export function countNewRecords(mutations: readonly MutationRecord[]): number {
  let added = 0;
  for (const mutation of mutations) {
    for (const node of mutation.addedNodes) {
      if (!(node instanceof Element)) continue;
      added += (node.matches(RECORD) ? 1 : 0) + node.querySelectorAll(RECORD).length;
    }
  }
  return added;
}

export function useMotionAllowed(enabled: boolean): boolean {
  const [reduced, setReduced] = useState(() => window.matchMedia('(prefers-reduced-motion: reduce)').matches);
  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const change = () => setReduced(query.matches);
    query.addEventListener('change', change);
    return () => query.removeEventListener('change', change);
  }, []);
  return enabled && !reduced;
}

export function usePinnedSelection(root: RefObject<HTMLElement>, selector = '[data-reader-answer], [data-reader-process]'): readonly string[] {
  const [keys, setKeys] = useState<readonly string[]>([]);
  useEffect(() => {
    const update = () => {
      const selection = document.getSelection();
      const range = selection && !selection.isCollapsed && selection.rangeCount ? selection.getRangeAt(0) : null;
      const next = range && root.current
        ? [...new Set(Array.from(root.current.querySelectorAll<HTMLElement>(selector))
          .filter(element => range.intersectsNode(element))
          .map(element => element.dataset.readerKey ?? element.dataset.readerProcessKey!).filter(Boolean))]
        : [];
      setKeys(previous => previous.length === next.length && previous.every((key, index) => key === next[index]) ? previous : next);
    };
    document.addEventListener('selectionchange', update);
    return () => document.removeEventListener('selectionchange', update);
  }, [root, selector]);
  return keys;
}

/**
 * The busy status line. `text` is the semantic phase label every skin reads;
 * while a turn is open it also carries the elapsed clock inside it. The terminal
 * skin instead reads the reference TUI's idiom — a breathing glyph, a per-turn
 * working verb and a tabular clock in its own slot — so `verb` and `clock` are
 * supplied as separate parts and the CSS picks which of the two the skin shows.
 */
export function StatusText({ text, ariaText, motion, shimmer = false, verb, clock, swapKey, detail }: {
  text: string; ariaText?: string; motion: boolean; shimmer?: boolean; verb?: string; clock?: string;
  /**
   * What the live turn is doing right now — the running command, path, or
   * query — shown beside the phase label when the reader's work-details level
   * asks for live detail. Decoration only: the live region keeps the phase.
   */
  detail?: string;
  /**
   * Identity for the swap animation, when it is not the label itself. A label
   * that embeds a ticking clock changes every second, and swapping on the text
   * then slides and blurs the whole sentence once a second; passing the phase
   * instead keeps that animation on real phase changes and lets the digits
   * change in place.
   */
  swapKey?: string;
}) {
  const ref = useRef<HTMLSpanElement>(null);
  const [visible, setVisible] = useState(() => !document.hidden);
  const [forcedColors, setForcedColors] = useState(() => window.matchMedia('(forced-colors: active)').matches);
  const allowed = motion && visible && !forcedColors;
  const key = swapKey ?? text;
  const [frame, setFrame] = useState<{
    key: string; text: string; id: number; phase: 'idle' | 'start' | 'running';
    outgoing: { text: string; id: number } | null;
  }>({ key, text, id: 0, phase: 'idle', outgoing: null });
  // Adjust before commit, so a new label cannot paint once before its entry state.
  // Reuse the previous incoming key: a rapid change exits from its current pose.
  if (frame.key !== key) setFrame({
    key, text, id: frame.id + 1, phase: allowed ? 'start' : 'idle',
    outgoing: allowed ? { text: frame.text, id: frame.id } : null,
  });
  // Same phase, new digits: update the painted string without re-animating it.
  else if (frame.text !== text) setFrame({ ...frame, text });
  useEffect(() => {
    const update = () => setVisible(!document.hidden);
    const query = window.matchMedia('(forced-colors: active)');
    const colors = () => setForcedColors(query.matches);
    document.addEventListener('visibilitychange', update);
    query.addEventListener('change', colors);
    return () => { document.removeEventListener('visibilitychange', update); query.removeEventListener('change', colors); };
  }, []);
  useLayoutEffect(() => {
    const id = frame.id;
    const settle = () => setFrame(current => current.id === id && current.outgoing
      ? { ...current, phase: 'idle', outgoing: null } : current);
    if (!allowed) { settle(); return; }
    if (!frame.outgoing || !ref.current) return;
    // Commit the supplied .is-enter-start pose before releasing CSS transitions.
    ref.current.getBoundingClientRect();
    let timer = 0;
    const tick = requestAnimationFrame(() => {
      setFrame(current => current.id === id ? { ...current, phase: 'running' } : current);
      timer = window.setTimeout(settle, 200); // 150ms swap + 50ms incoming gap.
    });
    return () => { cancelAnimationFrame(tick); window.clearTimeout(timer); };
  }, [frame.id, allowed]);
  const active = shimmer && allowed;
  const swapping = allowed && frame.outgoing !== null;
  // The terminal skin's spinner. It ticks only while the reading view is
  // actually showing a busy line, so it costs nothing at rest, and with motion
  // disallowed it holds one frame — which still says "running is happening"
  // without anything moving.
  const spinning = allowed && shimmer;
  const [tick, setTick] = useState(0);
  useEffect(() => {
    if (!spinning) return;
    const timer = window.setInterval(() => setTick(value => value + 1), SPINNER_INTERVAL_MS);
    return () => window.clearInterval(timer);
  }, [spinning]);
  return <span className={css.statusText} data-reader-status data-reader-busy={shimmer} data-reader-status-verb={verb !== undefined || undefined} data-ud-check="reader-status">
    {/* Decoration only: the spinner is the terminal skin's busy glyph and the
        live region below carries the phase for assistive tech. Rendered in
        every skin and hidden by CSS, like the rest of the decorative chrome. */}
    <span className={css.statusGlyph} aria-hidden="true">{spinning ? spinnerFrame(tick) : SPINNER_STILL_FRAME}</span>
    <span className={css.think} aria-hidden="true" data-active={active} data-reader-status-phase={swapping ? frame.phase : 'idle'} data-ud-motion="reader-thinking-state">
      <span className={css.thinkSizer}>{text}</span>
      {swapping && <span key={frame.outgoing!.id} className={`${css.thinkText} ${frame.phase === 'running' ? css.isExit : ''}`}
        data-reader-status-copy="outgoing" data-text={frame.outgoing!.text}>{frame.outgoing!.text}</span>}
      <span key={frame.id} ref={ref} className={`${css.thinkText} ${swapping && frame.phase === 'start' ? css.isEnterStart : ''}`}
        data-reader-status-copy="current" data-reader-shimmer={active || undefined} data-text={text}>{text}</span>
    </span>
    {verb !== undefined && <span className={css.statusVerb} aria-hidden="true">{verb}</span>}
    {detail !== undefined && <span className={css.statusDetail} data-reader-status-detail aria-hidden="true">{detail}</span>}
    {clock !== undefined && <span className={css.statusClock} data-reader-status-clock aria-hidden="true">{clock}</span>}
    <span className={css.srOnly} role="status" aria-live="polite" aria-atomic="true">{ariaText ?? text}</span>
  </span>;
}

export function Disclosure({ open, onChange, label, activity, summary, status, controls, buttonRef }: {
  open: boolean; onChange: (value: boolean) => void; label: ReactNode;
  /** The ranked action phrase and its family glyph: what a fold hides, in words. */
  activity?: { phrase: string; glyph: ComponentType<{ className?: string }> };
  summary?: string;
  status?: string; controls: string; buttonRef: RefObject<HTMLButtonElement>;
}) {
  const ActivityGlyph = activity?.glyph;
  return <div className={css.disclosure} data-reader-disclosure data-expanded={open}>
    <button ref={buttonRef} type="button" className={css.disclosureButton} aria-label={open ? ui('turn.foldAriaCollapse') : ui('turn.foldAriaExpand')} aria-expanded={open} aria-controls={controls} onClick={() => onChange(!open)}>
      {label}
      {/* What the fold hides, in the order a reader wants it: the family that did
          the work and what it did, then the raw counts. Rendered for every skin —
          the terminal skin draws them, the others hide the pixels and keep the
          text for assistive tech. */}
      {activity !== undefined && <span className={css.foldActivity} data-reader-fold-activity data-activity={activity.phrase}>
        {ActivityGlyph && <ActivityGlyph className={css.foldActivityGlyph} />}
        <span className={css.foldActivityPhrase}>{activity.phrase}</span>
      </span>}
      {summary !== undefined && <span className={css.frameCounts} data-reader-fold-summary>{summary}</span>}
      <svg className={css.chevron} data-open={open} viewBox="0 0 16 16" width="12" height="12" aria-hidden="true"><path d="m6 4 4 4-4 4" /></svg>
    </button>
    <div className={css.processMeta} data-reader-process-meta data-open={open} aria-hidden={!open}>
      <div className={css.processMetaInner}><div className={css.processMetaLine}>
        <span>{ui('turn.process')}</span>{status && <span className={css.meta}>{status}</span>}
      </div></div>
    </div>
  </div>;
}

/** Opening or closing one disclosure body. */
export const DISCLOSURE_SIZE_MS = 260;

/** Folding one retired narration out of the live stream. */
export const RETIRE_SIZE_MS = 220;

/** Supplemental details stay in source order beside their own narration. */
export function ProcessFragment({ open, motion, onRead, returnFocusTo, nodeKey, children, framed = false }: {
  open: boolean; motion: boolean; onRead: () => void; nodeKey: string;
  returnFocusTo: RefObject<HTMLElement>; children: ReactNode; framed?: boolean;
}) {
  const body = useRef<HTMLDivElement>(null);
  const running = useRef<Animation | null>(null);
  const previous = useRef(open);
  const [present, setPresent] = useState(open);
  useLayoutEffect(() => {
    const element = body.current;
    if (!element) return;
    const from = running.current ? element.getBoundingClientRect().height : previous.current ? element.scrollHeight : 0;
    running.current?.cancel();
    running.current = null;
    const changed = previous.current !== open;
    previous.current = open;
    if (open) setPresent(true);
    if (!open && element.contains(document.activeElement)) returnFocusTo.current?.focus();
    element.style.height = open ? 'auto' : '0px';
    const target = open ? element.scrollHeight : 0;
    if (!motion || !changed || Math.abs(from - target) < 1) {
      setPresent(open);
      return;
    }
    const animation = element.animate([{ height: `${from}px` }, { height: `${target}px` }], { duration: DISCLOSURE_SIZE_MS, easing: EASING, fill: 'both' });
    running.current = animation;
    // `fill: 'both'` holds whichever keyframe this animation stopped on, and the
    // body only becomes readable when the fill is dropped — here, by the cancel
    // below. An animation that never advances (re-run, unmount, a subtree the
    // compositor skips) never reaches `onfinish`, which would leave the row in the
    // DOM at zero height: clicked it, and nothing happened. The deadline commits
    // the same end state on a wall clock instead.
    return settleByDeadline(animation, () => {
      if (running.current !== animation) return;
      running.current = null;
      animation.cancel();
      setPresent(open);
    }, DISCLOSURE_SIZE_MS);
  }, [open, motion, returnFocusTo]);
  useEffect(() => () => { running.current?.cancel(); }, []);
  if (!open && !present) return null;
  return <div ref={body} className={css.disclosureBody} data-reader-process data-reader-process-key={nodeKey} data-ud-motion="reader-process-size"
    aria-hidden={!open} onPointerDown={() => { if (open) onRead(); }} onFocusCapture={() => { if (open) onRead(); }} {...(!open ? { inert: '' } : {})}>
    <div className={framed ? css.processFrame : css.processContents}>{children}</div>
  </div>;
}

/** Retire only narration that was actually visible; historical rows stay folded. */
export function RetiringContent({ visible, children }: { visible: boolean; children: ReactNode }) {
  const { enabled } = useContext(StreamMotionContext);
  const root = useRef<HTMLDivElement>(null);
  const animation = useRef<Animation | null>(null);
  const [present, setPresent] = useState(visible);
  const [focusHeld, setFocusHeld] = useState(false);
  useLayoutEffect(() => {
    const element = root.current;
    if (visible) {
      animation.current?.cancel(); animation.current = null;
      setPresent(true);
      return;
    }
    if (!element) return;
    if (element.contains(document.activeElement)) { setFocusHeld(true); return; }
    if (focusHeld) return;
    const from = element.getBoundingClientRect().height;
    animation.current?.cancel(); animation.current = null;
    if (!enabled || from < 1) { setPresent(false); return; }
    const next = element.animate([{ height: `${from}px`, opacity: 1 }, { height: '0px', opacity: 0 }], { duration: RETIRE_SIZE_MS, easing: EASING, fill: 'both' });
    animation.current = next;
    // A collapse that never reports finishing would leave the retired narration
    // pinned at its old height — and, because `present` never flips, in the tree.
    // The deadline completes the retirement regardless.
    return settleByDeadline(next, () => {
      if (animation.current !== next) return;
      animation.current = null;
      next.cancel();
      setPresent(false);
    }, RETIRE_SIZE_MS);
  }, [visible, enabled, focusHeld]);
  useEffect(() => () => animation.current?.cancel(), []);
  if (!visible && !present) return null;
  return <div ref={root} className={css.retiringContent} data-reader-retiring={visible ? 'visible' : 'retiring'} data-ud-motion="reader-progress-retire"
    onBlur={event => { if (!event.currentTarget.contains(event.relatedTarget)) setFocusHeld(false); }}>
    {children}
  </div>;
}

// DOM-only behavior: the native Session remains the sole source of business data.
export function useReadingScroll(root: RefObject<HTMLElement>, motion: boolean): { detached: boolean; unread: number; jump: () => void } {
  const port = useRef<HTMLElement | null>(null);
  const following = useRef(true);
  const anchor = useRef<{ element: HTMLElement; top: number } | null>(null);
  const [detached, setDetached] = useState(false);
  // How many readable records have arrived since the reader left the bottom.
  // The count is what makes the jump control worth pressing, so it is counted
  // on the same marker the anchor capture uses: `[data-reader-anchor]` is
  // already this view's definition of "a record a reader can read".
  const [unread, setUnread] = useState(0);
  const unreadCount = useRef(0);
  const clearUnread = () => {
    if (unreadCount.current === 0) return;
    unreadCount.current = 0;
    setUnread(0);
  };
  useLayoutEffect(() => {
    const content = root.current;
    if (!content) return;
    const scroll = content.closest<HTMLElement>('[data-conversation-scroll]') ?? content;
    port.current = scroll;
    let followFrame = 0;
    let lastFrameAt = 0;
    let lastWrittenTop: number | null = null;
    const selected = () => {
      const selection = document.getSelection();
      return selection && !selection.isCollapsed && selection.anchorNode && content.contains(selection.anchorNode);
    };
    // A focused text input pauses auto-follow; ordinary button focus must not
    // permanently detach the view from the newest content.
    const focusBlocks = () => {
      const active = document.activeElement;
      if (!active || !content.contains(active)) return false;
      return active instanceof HTMLElement && active.closest('textarea,input,[contenteditable=true],[role=textbox]') !== null;
    };
    const capture = () => {
      const top = scroll.getBoundingClientRect().top;
      const candidate = Array.from(content.querySelectorAll<HTMLElement>('[data-reader-anchor]')).find(element => element.getBoundingClientRect().bottom > top + 8);
      anchor.current = candidate ? { element: candidate, top: candidate.getBoundingClientRect().top } : null;
    };
    const onScroll = () => {
      // Our easing frames must not be mistaken for a user leaving the bottom.
      if (lastWrittenTop !== null && Math.abs(scroll.scrollTop - lastWrittenTop) < 1) return;
      following.current = scroll.scrollHeight - scroll.scrollTop - scroll.clientHeight < 72;
      setDetached(!following.current);
      if (!following.current) { cancelAnimationFrame(followFrame); followFrame = 0; }
      else clearUnread();
      capture();
    };
    const onWheel = (event: WheelEvent) => {
      cancelAnimationFrame(followFrame); followFrame = 0; lastWrittenTop = null;
      if (event.deltaY < 0) { following.current = false; setDetached(true); capture(); }
    };
    const onKey = (event: KeyboardEvent) => {
      if (event.target instanceof HTMLElement && event.target.closest('textarea,input,[contenteditable=true]')) return;
      if (['PageUp', 'Home', 'ArrowUp'].includes(event.key)) {
        cancelAnimationFrame(followFrame); followFrame = 0; lastWrittenTop = null;
        following.current = false; setDetached(true); capture();
      }
    };
    const writeTop = (top: number) => { scroll.scrollTop = top; lastWrittenTop = scroll.scrollTop; };
    /* Following is a chase, and its time constant is the whole feel of it.
     *
     * It was 52ms: a reader watching an answer stream in saw the text arrive and
     * then the viewport drift down to it a beat later, which reads as the view
     * lagging rather than as the text being new. 18ms closes ~60% of the
     * remaining gap per frame, so the lag stays within about one frame's worth
     * of growth and the bottom edge looks pinned to the text.
     *
     * It stays an eased chase rather than a bare `scrollTop = scrollHeight`,
     * because the easing is what makes a burst land smoothly instead of
     * snapping. `SNAP` ends the chase once the remainder is under a line:
     * easing a 3px gap across frames is pure latency, and it is also what kept
     * `detached` flickering for a frame at the tail of every burst. */
    const SNAP = 24;
    const follow = (now: number) => {
      followFrame = 0;
      if (!following.current || selected() || focusBlocks()) return;
      const gap = scroll.scrollHeight - scroll.clientHeight - scroll.scrollTop;
      const delta = Math.min(48, Math.max(1, now - lastFrameAt));
      lastFrameAt = now;
      if (!motion || Math.abs(gap) < SNAP) { writeTop(scroll.scrollHeight); capture(); return; }
      writeTop(scroll.scrollTop + gap * (1 - Math.exp(-delta / 18)));
      followFrame = requestAnimationFrame(follow);
    };
    const firstFrame = requestAnimationFrame(() => {
      if (following.current && !selected()) writeTop(scroll.scrollHeight);
      capture();
    });
    const observer = new ResizeObserver(() => {
      // A programmatic jump is animating: anchor compensation would fight its
      // smooth scroll and derail it. Yield until the jump releases the lock.
      if (jumpLock.active) return;
      if (selected()) return;
      if (following.current && !focusBlocks()) {
        if (!motion) writeTop(scroll.scrollHeight);
        else if (!followFrame) { lastFrameAt = performance.now(); followFrame = requestAnimationFrame(follow); }
      } else if (!following.current && anchor.current?.element.isConnected) {
        const delta = anchor.current.element.getBoundingClientRect().top - anchor.current.top;
        if (Math.abs(delta) > .5) writeTop(scroll.scrollTop + delta);
      }
      capture();
    });
    observer.observe(content);
    if (scroll !== content) observer.observe(scroll);
    // Count what arrives while the reader is away. A `ResizeObserver` cannot do
    // this — it reports that the content got taller, not how many records
    // arrived — and the count is the part of the control that answers "is it
    // worth going back for". Capped, because past a couple of digits the exact
    // number stops carrying information.
    const records = new MutationObserver(mutations => {
      if (following.current) return;
      const added = countNewRecords(mutations);
      if (added === 0) return;
      unreadCount.current = Math.min(UNREAD_CAP, unreadCount.current + added);
      setUnread(unreadCount.current);
    });
    records.observe(content, { childList: true, subtree: true });
    scroll.addEventListener('scroll', onScroll, { passive: true });
    scroll.addEventListener('wheel', onWheel, { passive: true });
    scroll.addEventListener('keydown', onKey);
    return () => {
      cancelAnimationFrame(firstFrame); cancelAnimationFrame(followFrame);
      observer.disconnect(); records.disconnect();
      scroll.removeEventListener('scroll', onScroll); scroll.removeEventListener('wheel', onWheel);
      scroll.removeEventListener('keydown', onKey);
    };
  }, [root, motion]);
  return { detached, unread, jump: () => {
    following.current = true; setDetached(false); clearUnread();
    // Same yield rule as rail jumps: nothing may fight this smooth scroll.
    jumpLock.active = true;
    setTimeout(() => { jumpLock.active = false; }, 1200);
    port.current?.scrollTo({ top: port.current.scrollHeight, behavior: 'smooth' });
  } };
}

/** Remember the reading position per session and restore it on return. */
export function useReadingPosition(root: RefObject<HTMLElement>, sessionId: string, ready: boolean): boolean {
  const key = `dsh-deckseek:reader:pos:${sessionId}`;
  const [restored, setRestored] = useState(false);
  const done = useRef(false);
  useLayoutEffect(() => {
    const content = root.current;
    if (!ready || !content || done.current) return;
    const scroll = content.closest<HTMLElement>('[data-conversation-scroll]') ?? content;
    if (typeof sessionStorage === 'undefined') return;
    let saved = 0;
    try { saved = Number(sessionStorage.getItem(key) ?? '0'); } catch { /* storage unavailable */ }
    if (Number.isFinite(saved) && saved > 480 && saved <= scroll.scrollHeight - scroll.clientHeight + 200) {
      // Restore after the initial follow frame so the reading-scroll follower
      // observes the jump as a user scroll and stops auto-following.
      requestAnimationFrame(() => { scroll.scrollTop = saved; });
      setRestored(true);
    }
    done.current = true;
  }, [ready, key, root]);
  useEffect(() => {
    const content = root.current;
    if (!content || typeof sessionStorage === 'undefined') return;
    const scroll = content.closest<HTMLElement>('[data-conversation-scroll]') ?? content;
    const save = () => { try { sessionStorage.setItem(key, String(scroll.scrollTop)); } catch { /* storage unavailable */ } };
    const timer = window.setInterval(save, 2000);
    window.addEventListener('beforeunload', save);
    return () => { window.clearInterval(timer); window.removeEventListener('beforeunload', save); };
  }, [key, root]);
  return restored;
}
