import { useSyncExternalStore } from 'react';
import type { Context } from '@deepseek-ai/cordis';
import type {} from '@deepseek-ai/dsh-api-session-controller/client';
import type { SessionId } from '@deepseek-ai/dsh-session/types';
import { resolveWorkspacePath } from '@deepseek-ai/dsh-util-workspace-path';
import type {} from '@deepseek-ai/dsh-client-ui-conversation/client';
import type {} from '@deepseek-ai/dsh-client-ui-renderer/client';
import type {} from '@deepseek-ai/dsh-client-ui-settings/client';
import type {} from '@deepseek-ai/dsh-client-ui-workspace/client';
import {
  DEFAULT_SCREEN_TEXTURE, DEFAULT_SKIN, DEFAULT_WORK_DETAIL, DECKSEEK_SETTINGS_NAMESPACE, SKIN_FIELD, TEXTURE_FIELD, WORK_DETAIL_FIELD,
  parseScreenTexture, parseSkin, parseWorkDetail, type ScreenTextureId, type SkinId, type WorkDetailId,
} from '../skin.js';
import type { DeckSeekSettings } from '../skin-settings.js';
import { DeckSeekSection } from './DeckSeekSection.js';
import { Reader } from './Reader.js';
import { createReaderStore } from './store.js';
import { installReaderEntry } from './entry.js';
import { ui } from './locale.js';
import type { DeckSeekSectionInjected, ReaderInjected } from './types.js';

export type { ReaderBlockOwner } from './types.js';
export { McpAppFrame } from './McpAppFrame.js';
export const name = 'dsh-deckseek-client';
export const inject = ['slots', 'sessions', 'configForms'];

export function apply(ctx: Context): void {
  const store = createReaderStore();
  // 0.1.7 replaced `ctx.settingsScope.bind({ namespace })` with the shared
  // config-form service, keyed by the Host plugin entry id — which is exactly
  // the settings namespace the entry's own Config schema declares.
  const form = ctx.configForms.get<DeckSeekSettings>(DECKSEEK_SETTINGS_NAMESPACE);
  // One hook instance shared by the reader view and the settings page, so both
  // read the same mirror and re-render on the same notification.
  const useSkin = (): SkinId => useSyncExternalStore(
    listener => form.subscribe(listener),
    () => parseSkin(form.getSnapshot().value?.skin),
    () => DEFAULT_SKIN,
  );
  const useWritable = (): boolean => useSyncExternalStore(
    listener => form.subscribe(listener),
    () => form.getSnapshot().writable,
    () => false,
  );
  const useWorkDetail = (): WorkDetailId => useSyncExternalStore(
    listener => form.subscribe(listener),
    () => parseWorkDetail(form.getSnapshot().value?.workDetail),
    () => DEFAULT_WORK_DETAIL,
  );
  const useTexture = (): ScreenTextureId => useSyncExternalStore(
    listener => form.subscribe(listener),
    () => parseScreenTexture(form.getSnapshot().value?.texture),
    () => DEFAULT_SCREEN_TEXTURE,
  );
  const setSkin = (next: SkinId): void => { void form.set(SKIN_FIELD, next); };
  const setTexture = (next: ScreenTextureId): void => { void form.set(TEXTURE_FIELD, next); };
  const setWorkDetail = (next: WorkDetailId): void => { void form.set(WORK_DETAIL_FIELD, next); };
  const faces = new Map<SessionId, ReaderInjected>();
  ctx.effect(() => () => { faces.clear(); });
  ctx.slots.inject('conversation.view', () => ctx.slots.register({
    name: 'conversation.view',
    id: 'reader',
    order: -5,
    label: () => ui('reader.tab'),
    locale: 'chat',
    children: { 'dsh-deckseek.block': { kind: 'chain', scope: 'session' } },
    store,
    inject: (sessionId: SessionId): ReaderInjected => {
      const existing = faces.get(sessionId);
      if (existing) return existing;
      const session = () => {
        const current = ctx.sessions.binding(sessionId)?.session;
        if (!current) throw new Error(ui('reader.sessionClosed'));
        return current;
      };
      const face: ReaderInjected = {
        loadOlder: async () => { await session().loadOlder(); },
        loadImage: async attachment => {
          const receipt = await session().readAttachment(attachment.attachmentId);
          if (!receipt.ok) throw new Error(receipt.error.message);
          return { data: Uint8Array.from(receipt.value.data), mediaType: receipt.value.attachment.mediaType };
        },
        // The host's own `forkAt` (`ui-chat/src/client/apply.ts`) is exactly this
        // pair of calls plus a trailing `increaseTitle: true`. It is rebuilt
        // rather than received because the host delivers it with
        // `ChatNodeOwnerProps`, and the reading view's seat
        // (`ConvViewOwnerProps`) never holds one — every prop this seat receives
        // is owned by the conversation view, which has no chat nodes to hand
        // down. Both services are already reachable from here: `sessions` is
        // declared in this plugin's `inject` list, and `uiWorkspace` is resolved
        // lazily so a deployment without a workspace browser degrades to a no-op
        // rather than refusing to load the plugin.
        forkAt: (seq: number) => {
          void ctx.sessions
            .fork({ sessionId, atSeq: seq, increaseTitle: true })
            .then(childId => { ctx.get('uiWorkspace')?.openSession(childId); })
            // A failed fork leaves the source view untouched, matching the host:
            // the session stays open and the reader keeps their place.
            .catch(() => {});
        },
        // The deployment's own opener, resolved lazily rather than declared as a
        // dependency: a deployment with no remote session panel should open
        // nothing and keep working, not refuse to load the plugin. Every failure
        // path here is a warning and a no-op — opening a file is a convenience,
        // and nothing about the reading view should depend on it.
        openFile: (path: string) => {
          try {
            const cwd = ctx.sessions?.list?.getSnapshot?.()?.byId[sessionId]?.cwd;
            // A folder request (`.` / empty) is the workspace itself: resolving it
            // again would look for `.` inside the workspace and open nothing.
            const target = path === '.' || path === ''
              ? cwd ?? '.'
              : cwd === undefined ? path : resolveWorkspacePath(cwd, path);
            const remote = ctx.get('remote.session') as
              { openWorkspacePath?: (arg: { path: string }) => Promise<{ ok?: boolean; error?: { message?: string } }> } | undefined;
            if (!remote?.openWorkspacePath) {
              console.warn('[dsh-deckseek] remote.session is not available; cannot open', target);
              return;
            }
            void remote.openWorkspacePath({ path: target }).then(result => {
              if (!result?.ok) console.warn('[dsh-deckseek] openWorkspacePath failed:', result?.error?.message);
            }).catch(error => { console.warn('[dsh-deckseek] openFile failed:', error); });
          } catch (error) {
            console.warn('[dsh-deckseek] openFile failed:', error);
          }
        },
        useSkin,
        useWorkDetail,
        useTexture,
        // Same writers the settings page holds, so a skin chosen from the
        // command palette lands in the same document as one chosen from the
        // settings page — there is one source of truth, not two.
        setSkin,
        setWorkDetail,
        setTexture,
      };
      faces.set(sessionId, face);
      return face;
    },
  }, Reader));
  ctx.slots.inject('settings.section', () => ctx.slots.register({
    name: 'settings.section',
    id: 'deckseek',
    order: 30,
    label: () => ui('settings.nav'),
    inject: (): DeckSeekSectionInjected => ({ useSkin, useWritable, setSkin, useWorkDetail, setWorkDetail, useTexture, setTexture }),
  }, DeckSeekSection));
  installReaderEntry(ctx);
}
